const toast=(m,undo)=>{document.querySelector('.toast')?.remove();const t=document.createElement('div');t.className='toast';t.innerHTML=`<span>${m}</span>${undo?'<button>Anulează</button>':''}`;document.body.append(t);t.querySelector('button')?.addEventListener('click',()=>{undo();t.remove()});setTimeout(()=>t.remove(),6000)};
const spark=()=>{const n=dim(month),a=Array(n+1).fill(0);by(month,'income').concat(by(month,'loan_received'),by(month,'loan_collect')).forEach(t=>a[+t.date.slice(8)]+=t.amount);tx().filter(t=>['expense','debt','loan_lent','loan_repay'].includes(t.type)&&t.account in {Card:1,Numerar:1}).forEach(t=>a[+t.date.slice(8)]-=t.amount);let c=0;const p=a.slice(1).map(v=>c+=v),mn=Math.min(...p,0),mx=Math.max(...p,1);return p.map((v,i)=>`${i/(n-1)*300},${60-(v-mn)/(mx-mn||1)*52}`).join(' ')};
